mapper.insert:
INSERT INTO matching_score_policy (
  policy_name, status, version, description, created_by, updated_by, created_at
) VALUES (
  #{policyName}, #{status}, #{version}, #{description,jdbcType=VARCHAR}, #{createdBy}, #{updatedBy}, NOW()
)

INSERT INTO matching_score_policy_item (
  policy_id, score_group, element_code, display_name, weight, sort_order, active_yn
) VALUES (
  #{policyId}, #{scoreGroup}, #{elementCode}, #{displayName}, #{weight}, #{sortOrder}, 'Y'
)

INSERT INTO matching_score_policy_history (
  policy_id, changed_by, before_json, after_json, change_reason, created_at
) VALUES (
  #{policyId}, #{changedBy}, #{beforeJson,jdbcType=VARCHAR}, #{afterJson,jdbcType=VARCHAR}, #{changeReason}, NOW()
)
